-- Spanish 2026 application form (Employment Application-ESP 2026, Jotform 263035461572051), created on 2026-10-31 by
-- scripts/jotform/clone-spanish-form.mjs as a clone of the English 2026 form. Same question IDs,
-- so the field map is copied from the English row; language 'es' applies the Spanish option rule
-- ("Yes/ Sí" -> "Yes") in clean.mjs. The 2025 Spanish form stays active until the careers page
-- links here; README "What the Spanish 2026 form created" has the switch-over steps.

insert into recruiting.forms (jotform_form_id, label, language, default_location, questions, field_map)
select
  '263035461572051',
  'Employment Application-ESP 2026 (Spanish)',
  'es',
  null,
  $json${"5":{"name":"ltpgtltspanStylecolor","order":"2","text":"<p><span style=\"color: #000000;\">Rexius is an equal opportunity employer. Please complete this form fully, honestly and accurate</span><span style=\"color: #000000;\">ly.</span><span style=\"color: #000000;\">We appreciate your interest in employment with Rexius.</span></p>\n<p>Rexius es un empleador que ofrece igualdad de oportunidades. Complete este formulario de manera completa, honesta y precisa. Agradecemos su interés en trabajar con Rexius.</p>","type":"control_text"},"9":{"name":"name","order":"17","text":"Name/ Nombre","type":"control_fullname"},"16":{"name":"employmentApplication","order":"1","text":"Employment Application/ Solicitud de empleo","type":"control_head"},"21":{"name":"name21","order":"24","text":"Preferred Contact Method/ Método de contacto preferido","type":"control_checkbox","options":{"Phone/ Teléfono":"Phone/ Teléfono","Email/ Correo electrónico":"Email/ Correo electrónico"}},"22":{"name":"emailAddress","order":"23","text":"Email Address/ Correo electrónico","type":"control_email"},"30":{"name":"driverLicense30","order":"30","text":"Driver License number/ Número de licencia de conducir","type":"control_textbox"},"31":{"name":"expirationDate31","order":"31","text":"Expiration Date/ Fecha de vencimiento","type":"control_datetime"},"35":{"name":"classOr35","order":"32","text":"Class or Type of License/ Clase o tipo de licencia","type":"control_textbox"},"41":{"name":"jobInterest","order":"3","text":"Job Interest/ Interés laboral","type":"control_head"},"57":{"name":"educationAnd57","order":"36","text":"Education and Training/ Educación y capacitación","type":"control_head"},"66":{"name":"pleaseList66","order":"35","text":"Please list any currently valid and special motor vehicle, operator licenses or trade/craft certifications you hold./ Enumere las licencias especiales de vehículos motorizados u operador, o certificaciones de oficio, que tenga vigentes.","type":"control_textarea"},"70":{"name":"workHistory","order":"38","text":"Work History/ Historial laboral","type":"control_head"},"72":{"name":"1Name","order":"43","text":"1. Name of Employer/ 1. Nombre del empleador","type":"control_textbox"},"75":{"name":"phoneNumber","order":"45","text":"Phone number/ Número de teléfono","type":"control_phone"},"76":{"name":"yourJob","order":"46","text":"Your Job Title/ Su puesto","type":"control_textbox"},"80":{"name":"supervisorsName80","order":"51","text":"Supervisor’s Name/ Nombre del supervisor","type":"control_textbox"},"81":{"name":"supervisorsTitletitulo81","order":"52","text":"Supervisor’s Title/ Puesto del supervisor","type":"control_textbox"},"83":{"name":"2Name","order":"55","text":"2. Name of Employer/ 2. Nombre del empleador","type":"control_textbox"},"85":{"name":"location85","order":"56","text":"Location/ Ubicación","type":"control_textbox"},"86":{"name":"phoneNumber86","order":"57","text":"Phone number/ Número de teléfono","type":"control_phone"},"87":{"name":"yourJob87","order":"58","text":"Your Job Title /Responsibility/ Su puesto / responsabilidad","type":"control_textbox"},"89":{"name":"divider89","order":"66","type":"control_divider"},"92":{"name":"supervisorsName","order":"63","text":"Supervisor’s Name/ Nombre del supervisor","type":"control_textbox"},"93":{"name":"supervisorsTitletitulo93","order":"64","text":"Supervisor’s Title/ Puesto del supervisor","type":"control_textbox"},"94":{"name":"reasonFor","order":"65","text":"Reason for leaving (please be specific)/ Motivo de la salida (sea específico)","type":"control_textbox"},"95":{"name":"3Name","order":"67","text":"3. Name of Employer/ 3. Nombre del empleador","type":"control_textbox"},"98":{"name":"phoneNumber98","order":"69","text":"Phone number/ Número de teléfono","type":"control_phone"},"99":{"name":"yourJob99","order":"70","text":"Your Job Title / Responsibility/ Su puesto / responsabilidad","type":"control_textbox"},"105":{"name":"supervisorsName105","order":"75","text":"Supervisor’s Name/ Nombre del supervisor","type":"control_textbox"},"106":{"name":"supervisorsTitletitulo106","order":"76","text":"Supervisor’s Title/ Puesto del supervisor","type":"control_textbox"},"107":{"name":"reasonFor107","order":"77","text":"Reason for leaving (please be specific)/ Motivo de la salida (sea específico)","type":"control_textbox"},"189":{"name":"jobrelatedBackground","order":"82","text":"Job-Related Background/ Antecedentes relacionados con el trabajo","type":"control_head"},"216":{"name":"agreementAnd","order":"84","text":"Agreement and Release/ Acuerdo y liberación","type":"control_head"},"217":{"name":"ltpgtltspanStylefontweight217","order":"85","text":"<p><span style=\"font-weight: bold; color: #000000;\">PLEASE READ THE ENTIRE FOLLOWING SECTION </span><span style=\"font-weight: bold; color: #000000;\">HERE AND ON THE NEXT PAGE</span> <span style=\"font-weight: bold; color: #000000;\">BEFORE SIGNING.</span></p>\r\n<p><span style=\"color: #000000;\">Initial each section in the center column indicating you have read and agree with that section. Sign the bottom of this application on the following page.</span></p>\n<p><span style=\"font-weight: bold; color: #000000;\">LEA TODA LA SIGUIENTE SECCIÓN, AQUÍ Y EN LA PÁGINA SIGUIENTE, ANTES DE FIRMAR.</span></p>\n<p><span style=\"color: #000000;\">Ponga sus iniciales en cada sección, en la columna central, para indicar que la ha leído y está de acuerdo con ella. Firme al final de esta solicitud en la página siguiente.</span></p>","type":"control_text"},"218":{"name":"withThis","order":"86","text":"WITH THIS APPLICATION BY MY SIGNATURE BELOW I AGREE TO ALL OF THE FOLLOWING TERMS:/ CON ESTA SOLICITUD, POR MI FIRMA A CONTINUACIÓN, ACEPTO TODOS LOS TÉRMINOS SIGUIENTES:","type":"control_head"},"219":{"name":"ltpgtltspanStylefontweight219","order":"87","text":"<p><span style=\"font-weight: bold; color: #000000;\">Term, Condition, Expectation and/or Agreement</span></p>\r\n<p>I certify that the information I have provided on this Application Form and on my Resume (if applicable) is true and correct to the best of my knowledge.</p>\r\n<p>I understand that any misrepresentation, falsification, or omission of material information on this application may result in my failure to receive an offer, or, if I am hired, in my termination from employment.</p>\n<p><span style=\"font-weight: bold; color: #000000;\">Término, condición, expectativa y/o acuerdo</span></p>\n<p>Certifico que la información que he proporcionado en este formulario de solicitud y en mi currículum (si corresponde) es verdadera y correcta a mi leal saber y entender.</p>\n<p>Entiendo que cualquier tergiversación, falsificación u omisión de información importante en esta solicitud puede dar lugar a que no reciba una oferta o, si soy contratado, a la terminación de mi empleo.</p>","type":"control_text"},"228":{"name":"alcoholAnd228","order":"99","text":"Alcohol and Drug Testing Consent Form/ Formulario de consentimiento para pruebas de alcohol y drogas","type":"control_head"},"238":{"name":"rexiusHas238","order":"100","text":"Rexius has requested that I take a drug/alcohol test under its Alcohol & Drug Policy as part of my application for employment. Accordingly, by my signature below, herby authorize Rexius, the Medical Review Officer and licensed laboratory selected by Rexius to perform a urinalysis on a urine specimen provided by me to test for drug use. I consent to this test and I also give my permission to the laboratory and Medical Review Officer to release the results of this drug test to Rexius. I agree that Rexius may use these results to determine my suitability for employment. If I am employed by Rexius I agree to any drug/alcohol testing the Company may require under its Alcohol and Drug Policy. If the laboratory finds the test invalid, and if the laboratory, Medical Review Officer or Rexius believe another test is appropriate, I agree to submit another specimen(s) for further testing. I understand that I will not be informed of the results of my pre-employment drug test unless I request it within 60 days of being notified of the disposition of my application./ Rexius ha solicitado que me someta a una prueba de drogas/alcohol según su Política de Alcohol y Drogas como parte de mi solicitud de empleo. En consecuencia, mediante mi firma a continuación, autorizo a Rexius, al Oficial de Revisión Médica y al laboratorio con licencia seleccionado por Rexius a realizar un análisis de orina en una muestra proporcionada por mí para detectar el uso de drogas. Consiento esta prueba y también doy mi permiso al laboratorio y al Oficial de Revisión Médica para divulgar los resultados de esta prueba de drogas a Rexius. Acepto que Rexius puede utilizar estos resultados para determinar mi idoneidad para el empleo. Si Rexius me emplea, acepto cualquier prueba de drogas/alcohol que la Compañía pueda requerir según su Política de Alcohol y Drogas. Si el laboratorio determina que la prueba no es válida, y si el laboratorio, el Oficial de Revisión Médica o Rexius consideran que corresponde otra prueba, acepto proporcionar otra(s) muestra(s) para pruebas adicionales. Entiendo que no se me informará de los resultados de mi prueba de drogas previa al empleo a menos que lo solicite dentro de los 60 días posteriores a la notificación de la decisión sobre mi solicitud.","type":"control_signature"},"261":{"name":"availableStart261","order":"16","text":"Available Start Date/ Fecha disponible para empezar","type":"control_datetime"},"262":{"name":"personalInformation262","order":"15","text":"Personal Information/ Información personal","type":"control_head"},"263":{"name":"address","order":"18","text":"Address/ Dirección","type":"control_address"},"264":{"name":"phoneNumber264","order":"19","text":"Phone Number/ Número de teléfono","type":"control_phone"},"265":{"name":"alternatePhone265","order":"21","text":"Alternate Phone Number/ Número de teléfono alternativo","type":"control_phone"},"266":{"name":"phoneType","order":"20","text":"Phone Type/ Tipo de teléfono","type":"control_radio","options":{"Home/ Casa":"Home/ Casa","Cell/ Celular":"Cell/ Celular"}},"267":{"name":"phoneType267","order":"22","text":"Phone Type/ Tipo de teléfono","type":"control_radio","options":{"Home/ Casa":"Home/ Casa","Cell/ Celular":"Cell/ Celular"}},"268":{"name":"name268","order":"8","text":"How did you learn about this job position?/ ¿Cómo se enteró de este puesto de trabajo?","type":"control_checkbox","options":{"Indeed.com":"Indeed.com","Rexius.com":"Rexius.com","Google":"Google","Facebook":"Facebook","Craigslist.com":"Craigslist.com","I am a Previous Employee/ Soy ex empleado":"I am a Previous Employee/ Soy ex empleado","Walk In/ Me presenté en persona":"Walk In/ Me presenté en persona","Other/ Otro":"Other/ Otro"}},"272":{"name":"haveYou","order":"11","text":"Have you ever worked for Rexius or its affiliates before?/ ¿Ha trabajado antes para Rexius o sus afiliados?","type":"control_radio","options":{"Yes/ Sí":"Yes/ Sí","No":"No"}},"273":{"name":"ifYes273","order":"12","text":"If yes, please give dates of employment, location, and job title./ En caso afirmativo, indique las fechas de empleo, la ubicación y el puesto.","type":"control_textarea"},"274":{"name":"haveYou274","order":"13","text":"Have you ever applied for work with Rexius or its affiliates before?/ ¿Ha solicitado antes trabajo con Rexius o sus afiliados?","type":"control_radio","options":{"Yes/ Sí":"Yes/ Sí","No":"No"}},"275":{"name":"ifYes275","order":"14","text":"If yes, please give date, location, and job for which you applied./ En caso afirmativo, indique la fecha, la ubicación y el puesto que solicitó.","type":"control_textarea"},"276":{"name":"youMay276","order":"78","text":"You may comment on any other special qualifications you have related to this job or this company./ Puede comentar cualquier otra cualificación especial que tenga relacionada con este trabajo o esta empresa.","type":"control_textarea"},"280":{"name":"location","order":"44","text":"Location/ Ubicación","type":"control_textbox"},"287":{"name":"locationUbicacion287","order":"68","text":"Location/ Ubicación","type":"control_textbox"},"311":{"name":"areYou","order":"25","text":"Are you at least 18 years of Age?/ ¿Tiene al menos 18 años de edad?","type":"control_radio","options":{"Yes/ Sí":"Yes/ Sí","No":"No"}},"312":{"name":"canYou","order":"26","text":"Can you, upon hiring, provide appropriate identification documenting and verifying your identity and your legal right to work in the USA?/ ¿Puede, al ser contratado, presentar identificación adecuada que documente y verifique su identidad y su derecho legal a trabajar en los EE. UU.?","type":"control_radio","options":{"Yes/ Sí":"Yes/ Sí","No":"No"}},"313":{"name":"regardingThejob313","order":"83","text":"Can you fulfill the job duties and responsibilities of the position(s) for which you are applying as they have been described to you through our written job description(s), with or without a reasonable accommodation?/ ¿Puede cumplir con los deberes y responsabilidades del puesto o los puestos que solicita, tal como se le han descrito en nuestra(s) descripción(es) de puesto por escrito, con o sin un ajuste razonable?","type":"control_radio","options":{"Yes/ Sí":"Yes/ Sí","No":"No"}},"322":{"name":"rexiusBelieves322","order":"97","text":"Rexius believes that use of drugs or alcohol in the workplace is an unsafe work practice and creates increased risk to the consumer, fellow employees, customers and the public. Rexius is a Drug-Free and Alcohol-Free workplace. Use of illegal substances or abuse of controlled substances may result in disciplinary action or termination of employment.If employed, do you agree to abide by the Rexius Drug-Free and Alcohol-Free workplace standards?/ Rexius considera que el uso de drogas o alcohol en el lugar de trabajo es una práctica laboral insegura y crea un mayor riesgo para el consumidor, los compañeros de trabajo, los clientes y el público. Rexius es un lugar de trabajo libre de drogas y alcohol. El uso de sustancias ilegales o el abuso de sustancias controladas puede dar lugar a medidas disciplinarias o a la terminación del empleo. Si es contratado, ¿acepta cumplir con las normas de Rexius de un lugar de trabajo libre de drogas y alcohol?","type":"control_radio","options":{"Yes/ Sí":"Yes/ Sí","No":"No"}},"323":{"name":"ifPresently","order":"42","text":"If presently employed, may we contact your current employer to verify employment?/ Si está empleado actualmente, ¿podemos contactar a su empleador actual para verificar su empleo?","type":"control_radio","options":{"Yes/ Sí":"Yes/ Sí","No":"No","Unemployed/NA/ Desempleado / No aplica":"Unemployed/NA/ Desempleado / No aplica"}},"324":{"name":"initials","order":"88","text":"Initials/ Iniciales","type":"control_textbox"},"325":{"name":"ltpgtltspanStylefontweight","order":"89","text":"<p><span style=\"font-weight: bold; color: #000000;\">Term, Condition, Expectation and/or Agreement</span></p>\r\n<p>In the event that I am requested to undergo a medical examination or evaluation as a part of the job placement process of the Company, I agree to supply only information which is true and correct to the best of my knowledge.</p>\r\n<p>If the Company determines that I have made any false oral or written statements, misrepresentations or omissions of material information to them or to the physician or their representative, the Company is entitled to rescind my conditional offer of employment or terminate my employment at any time.</p>\n<p><span style=\"font-weight: bold; color: #000000;\">Término, condición, expectativa y/o acuerdo</span></p>\n<p>En caso de que se me pida someterme a un examen o evaluación médica como parte del proceso de colocación laboral de la Compañía, acepto proporcionar únicamente información verdadera y correcta a mi leal saber y entender.</p>\n<p>Si la Compañía determina que he hecho declaraciones falsas, orales o escritas, tergiversaciones u omisiones de información importante a la Compañía, al médico o a su representante, la Compañía tiene derecho a retirar mi oferta condicional de empleo o a terminar mi empleo en cualquier momento.</p>","type":"control_text"},"326":{"name":"initials326","order":"90","text":"Initials/ Iniciales","type":"control_textbox"},"327":{"name":"ltpgtltspanStylefontweight327","order":"91","text":"<p><span style=\"font-weight: bold; color: #000000;\">Term, Condition, Expectation and/or Agreement</span></p>\n<p>I authorize any person, school, current employer, past employer, physician or organization with knowledge of me or my work to provide the Company or its agent or representative with any information or opinion about me in response to an inquiry by the Company.</p>\n<p>I release any such person, employer, physician or organization from any legal liability in making such statements or furnishing any and all information to the Company or to its representative or agent.</p>\n<p><span style=\"font-weight: bold; color: #000000;\">Término, condición, expectativa y/o acuerdo</span></p>\n<p>Autorizo a cualquier persona, escuela, empleador actual, empleador anterior, médico u organización que tenga conocimiento de mí o de mi trabajo a proporcionar a la Compañía, o a su agente o representante, cualquier información u opinión sobre mí en respuesta a una consulta de la Compañía.</p>\n<p>Eximo a dicha persona, empleador, médico u organización de toda responsabilidad legal por hacer tales declaraciones o por proporcionar cualquier información a la Compañía o a su representante o agente.</p>","type":"control_text"},"328":{"name":"initials328","order":"92","text":"Initials/ Iniciales","type":"control_textbox"},"329":{"name":"ltpgtltspanStylefontweight329","order":"93","text":"<p><span style=\"font-weight: bold; color: #000000;\">Term, Condition, Expectation and/or Agreement</span></p>\r\n<p>I authorize the Company, its agents, or representatives to check references regarding my employment and investigate any of the statements or answers provided by me on this application or made directly to a company representative. The only exception to this authorization is where I have specifically requested in writing on this application form that no such inquiry be made.</p>\n<p><span style=\"font-weight: bold; color: #000000;\">Término, condición, expectativa y/o acuerdo</span></p>\n<p>Autorizo a la Compañía, a sus agentes o representantes a verificar referencias sobre mi empleo y a investigar cualquiera de las declaraciones o respuestas que he dado en esta solicitud o directamente a un representante de la Compañía. La única excepción a esta autorización es cuando yo haya solicitado específicamente por escrito, en este formulario de solicitud, que no se haga tal consulta.</p>","type":"control_text"},"330":{"name":"initials330","order":"94","text":"Initials/ Iniciales","type":"control_textbox"},"331":{"name":"ltpgtltspanStylefontweight331","order":"95","text":"<p><span style=\"font-weight: bold; color: #000000;\">Term, Condition, Expectation and/or Agreement</span></p>\n<p>I understand that my employment at this Company is on an “at will” (that is, mutual consent) basis. Therefore I agree that either I or the Company has the proper right to terminate my employment with or without cause at any time.</p>\n<p><span style=\"font-weight: bold; color: #000000;\">Término, condición, expectativa y/o acuerdo</span></p>\n<p>Entiendo que mi empleo en esta Compañía es \"a voluntad\" (es decir, por consentimiento mutuo). Por lo tanto, acepto que tanto yo como la Compañía tenemos el derecho de terminar mi empleo, con o sin causa, en cualquier momento.</p>","type":"control_text"},"332":{"name":"initials332","order":"96","text":"Initials/ Iniciales","type":"control_textbox"},"333":{"name":"iHave","order":"98","text":"I have read and understood, and I agree to this entire section above, entitled AGREEMENT & RELEASE./ He leído y comprendido, y acepto toda la sección anterior, titulada ACUERDO Y LIBERACIÓN.","type":"control_signature"},"340":{"name":"whatPosition340","order":"6","text":"What position are you applying for in Eugene/Springfield?/ ¿Qué puesto está solicitando en Eugene/Springfield?","type":"control_dropdown","options":{"Irrigation Installation Crew Member":"Irrigation Installation Crew Member","Commercial Landscape Project Lead":"Commercial Landscape Project Lead","Commercial Landscape Crew Member":"Commercial Landscape Crew Member","Digital Marketer":"Digital Marketer","Landscape Maintenance Crew Member":"Landscape Maintenance Crew Member","Commercial Landscape Crew Lead":"Commercial Landscape Crew Lead","Flatbed Truck Driver":"Flatbed Truck Driver","Experienced Irrigation Technician":"Experienced Irrigation Technician","Landscape Maintenance Crew Leader":"Landscape Maintenance Crew Leader","Heavy Diesel Truck Mechanic":"Heavy Diesel Truck Mechanic","Any":"Any"}},"341":{"name":"whatPosition341","order":"7","text":"What position are you applying for in Central Oregon?/ ¿Qué puesto está solicitando en Central Oregon?","type":"control_dropdown","options":{"Landscape Maintenance Crew Member":"Landscape Maintenance Crew Member","Landscape Maintenance Crew Lead":"Landscape Maintenance Crew Lead","Landscape Construction Crew Member":"Landscape Construction Crew Member","Landscape Construction Lead":"Landscape Construction Lead","Irrigation Service Technician":"Irrigation Service Technician","Any":"Any"}},"342":{"name":"whatLocation","order":"4","text":"What location are you applying to?/ ¿A qué ubicación está solicitando?","type":"control_dropdown","options":{"Eugene-Springfield":"Eugene-Springfield","Central Oregon":"Central Oregon","Lake Oswego":"Lake Oswego"}},"343":{"name":"whatPosition","order":"5","text":"What position are you applying for in Lake Oswego?/ ¿Qué puesto está solicitando en Lake Oswego?","type":"control_dropdown","options":{"Blower Truck Operator":"Blower Truck Operator","Blower Truck Crew Member":"Blower Truck Crew Member","Any":"Any"}},"344":{"name":"pleaseCheck","order":"37","text":"Please check your highest level of education:/ Marque su nivel más alto de educación:","type":"control_radio","options":{"None/ Ninguno":"None/ Ninguno","GED":"GED","High School Diploma/ Diploma de preparatoria":"High School Diploma/ Diploma de preparatoria","Certification(s)/ Certificación(es)":"Certification(s)/ Certificación(es)","Associates Degree/ Título técnico (Associate)":"Associates Degree/ Título técnico (Associate)","Bachelor's Degree/ Licenciatura":"Bachelor's Degree/ Licenciatura","Graduate Degree/ Posgrado":"Graduate Degree/ Posgrado"}},"347":{"name":"submit","order":"101","text":"Submit/ Enviar","type":"control_button"},"348":{"name":"startDate","order":"49","text":"Start Date (MM/YEAR)/ Fecha de inicio (MM/AÑO)","type":"control_textbox"},"349":{"name":"startAnd349","order":"61","text":"Start Date (MM/YEAR)/ Fecha de inicio (MM/AÑO)","type":"control_textbox"},"350":{"name":"startAnd350","order":"73","text":"Start Date (MM/YEAR)/ Fecha de inicio (MM/AÑO)","type":"control_textbox"},"352":{"name":"reasonFor352","order":"53","text":"Reason for leaving (please be specific)/ Motivo de la salida (sea específico)","type":"control_textbox"},"355":{"name":"whoReferred","order":"9","text":"Who referred you?/ ¿Quién lo refirió?","type":"control_textbox"},"362":{"name":"input362","order":"39","text":"<p><strong>Please list your <span style=\"text-decoration: underline;\">complete</span> job history in order of occurance. Begin with your current or most recent job (if unemployed). </strong></p>\n<p><strong>Enumere su historial de trabajo completo en orden. Comience con su trabajo actual o más reciente (si está desempleado).</strong></p>","type":"control_text"},"363":{"name":"input363","order":"48","text":"<p><strong>Dates of employment:</strong></p>\n<p><strong>Fechas de empleo:</strong></p>","type":"control_text"},"364":{"name":"ltpgtltstronggtdatesOf","order":"60","text":"<p><strong>Dates of employment:</strong></p>\n<p><strong>Fechas de empleo:</strong></p>","type":"control_text"},"365":{"name":"ltpgtltstronggtdatesOf365","order":"72","text":"<p><strong>Dates of employment:</strong></p>\n<p><strong>Fechas de empleo:</strong></p>","type":"control_text"},"368":{"name":"input368","order":"33","text":"<p>I, the undersigned, hereby authorize Rexius Forest By-Products, Inc. to procure a Motor Vehicle Record (MVR) report. I understand that this report may include information about my driving record, including but not limited to traffic citations, accidents, driving offenses, and other related data. I acknowledge that Rexius may rely on this report to make decisions about my application, employment, or other related considerations.</p>\r\n<p>I understand that I have rights under the Fair Credit Reporting Act (FCRA), including the right to know if adverse action has been taken based on the information in the MVR report, and the right to verify the accuracy and completeness of any information provided by the consumer reporting agency.</p>\r\n<p>I acknowledge that this authorization will remain in effect until I revoke it in writing, and I agree that a copy of this authorization is as valid as the original.</p>\r\n<p>By signing below, I affirm my understanding and consent to the above terms.</p>\n<p>Yo, el abajo firmante, autorizo a Rexius Forest By-Products, Inc. a obtener un informe del Registro de Vehículos Motorizados (MVR). Entiendo que este informe puede incluir información sobre mi historial de manejo, que incluye, entre otros, citaciones de tránsito, accidentes, infracciones de manejo y otros datos relacionados. Reconozco que Rexius puede basarse en este informe para tomar decisiones sobre mi solicitud, mi empleo u otras consideraciones relacionadas.</p>\n<p>Entiendo que tengo derechos bajo la Ley de Informes de Crédito Justos (FCRA), incluido el derecho a saber si se ha tomado una medida adversa basada en la información del informe MVR, y el derecho a verificar la exactitud e integridad de cualquier información proporcionada por la agencia de informes del consumidor.</p>\n<p>Reconozco que esta autorización permanecerá vigente hasta que la revoque por escrito, y acepto que una copia de esta autorización tiene la misma validez que el original.</p>\n<p>Al firmar a continuación, afirmo que comprendo y acepto los términos anteriores.</p>","type":"control_text"},"369":{"name":"signature","order":"34","text":"Signature/ Firma","type":"control_signature"},"370":{"name":"input370","order":"29","text":"<p>You selected to apply for a job which requires driving a company vehicle. Please fill out the information below.</p>\n<p>Seleccionó un puesto que requiere conducir un vehículo de la empresa. Complete la siguiente información.</p>","type":"control_text"},"372":{"name":"pleaseList","order":"41","text":"Please list any relevant skills or experiences./ Enumere cualquier habilidad o experiencia relevante.","type":"control_textarea"},"377":{"name":"endDate","order":"50","text":"End Date (MM/YEAR)/ Fecha de fin (MM/AÑO)","type":"control_textbox"},"378":{"name":"endDate378","order":"62","text":"End Date (MM/YEAR)/ Fecha de fin (MM/AÑO)","type":"control_textbox"},"379":{"name":"endDate379","order":"74","text":"End Date (MM/YEAR)/ Fecha de fin (MM/AÑO)","type":"control_textbox"},"380":{"name":"pleaseDescribe","order":"47","text":"Please describe your role and responsibilities/ Describa su función y responsabilidades","type":"control_textarea"},"381":{"name":"pleaseDescribe381","order":"59","text":"Please describe your role and responsibilities/ Describa su función y responsabilidades","type":"control_textarea"},"382":{"name":"pleaseDescribe382","order":"71","text":"Please describe your role and responsibilities/ Describa su función y responsabilidades","type":"control_textarea"},"384":{"name":"howDid","order":"10","text":"How did you learn about the position?/ ¿Cómo se enteró del puesto?","type":"control_textbox"},"385":{"name":"ifYou385","order":"40","text":"If you have not yet had a job or are a student, please check the appropriate box below./ Si aún no ha tenido un trabajo o es estudiante, marque la casilla correspondiente.","type":"control_checkbox","options":{"I am currently a student/ Actualmente soy estudiante":"I am currently a student/ Actualmente soy estudiante","I do not have job experience to enter/ No tengo experiencia laboral que ingresar":"I do not have job experience to enter/ No tengo experiencia laboral que ingresar"}},"386":{"name":"doYou","order":"27","text":"Do you have forklift experience?/ ¿Tiene experiencia con montacargas?","type":"control_radio","options":{"Yes/ Sí":"Yes/ Sí","No":"No"}},"387":{"name":"ifYou387","order":"79","text":"If you have a resume you may upload it here:/ Si tiene un currículum, puede subirlo aquí:","type":"control_fileupload"},"389":{"name":"divider389","order":"54","text":"Divider","type":"control_divider"},"393":{"name":"ifYou","order":"80","text":"If you have a portfolio you may upload it here:/ Si tiene un portafolio, puede subirlo aquí:","type":"control_fileupload"},"394":{"name":"typeA","order":"81","text":"Link to Portfolio/ Enlace a su portafolio","type":"control_textbox"},"395":{"name":"doYou395","order":"28","text":"Do you have a valid Herbicide Spray Applicators License, or a valid Apprentice Herbicide Spray Applicators License?/ ¿Tiene una licencia vigente de aplicador de herbicidas, o una licencia vigente de aprendiz de aplicador de herbicidas?","type":"control_dropdown","options":{"Yes/ Sí":"Yes/ Sí","No":"No"}}}$json$::jsonb,
